import React, { useState } from 'react';
import * as ImagePicker from 'expo-image-picker';
import { ArrowLeft, CalendarDays, Check, ChevronRight, ClipboardList, Dumbbell, FileChartColumn, Image as ImageIcon, Plus, Search, Trash2, TrendingUp, UserCheck, Video, WalletCards } from 'lucide-react-native';
import { Image as RNImage, Pressable, ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';
import { Avatar, Badge, Card, SectionHeader, StatCard } from '../components/UI';
import { colors } from '../theme';
import { Client, ClientProfile, ClientTrainingPlan, Exercise, PlanWeek, Workout } from '../types';

const formatBirthDate = (value: string) => {
  const digits = value.replace(/\D/g, '').slice(0, 8);
  if (digits.length <= 2) return digits;
  if (digits.length <= 4) return `${digits.slice(0, 2)}/${digits.slice(2)}`;
  return `${digits.slice(0, 2)}/${digits.slice(2, 4)}/${digits.slice(4)}`;
};

function ClientRow({ client, onPress }: { client: Client; onPress: () => void }) {
  const tone = client.status === 'Ativo' ? 'green' : client.status === 'Inativo' ? 'red' : 'orange';
  const label = client.accessStatus === 'Convite enviado' ? 'Convite enviado' : client.status;
  return <Pressable onPress={onPress} style={styles.clientRow}><Avatar initials={client.initials}/><View style={styles.clientCopy}><Text style={styles.clientName}>{client.name}</Text><Text style={styles.clientMeta}>{client.goal || 'Objetivo não informado'} · {client.lastActivity}</Text></View><Badge label={label} tone={client.accessStatus === 'Convite enviado' ? 'orange' : tone}/><ChevronRight size={17} color={colors.subtle}/></Pressable>;
}

export function TrainerDashboard({ clients, plans, onClient }: { clients: Client[]; plans: Record<string, ClientTrainingPlan>; onClient: (client: Client) => void }) {
  const monthlyRevenue = clients.filter((client) => client.status !== 'Inativo').reduce((total, client) => total + client.monthlyFee, 0);
  const payingClients = clients.filter((client) => client.status !== 'Inativo').length;
  const reviewSheets = clients.flatMap((client) => client.status === 'Inativo' ? [] : (plans[client.id]?.workouts ?? []).filter((workout) => workout.expiresAt && new Date(workout.expiresAt).getTime() >= Date.now() && new Date(workout.expiresAt).getTime() - Date.now() <= 7 * 86400000).map((workout) => ({ client, workout })));
  const received = Math.round(monthlyRevenue * .85);
  const pending = monthlyRevenue - received;
  const money = (value: number) => value.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
  return <ScrollView contentContainerStyle={styles.page} showsVerticalScrollIndicator={false}>
    <Text style={styles.muted}>Bom dia, Bruno</Text><Text style={styles.pageTitle}>Visão do negócio</Text>
    <Card style={styles.financeCard}><View style={styles.financeTop}><View style={styles.financeIcon}><WalletCards size={21} color={colors.primary}/></View><Text style={styles.financeLabel}>MENSALIDADES ATIVAS</Text></View><Text style={styles.financeValue}>{money(monthlyRevenue)}</Text><View style={styles.financeSplit}><View><Text style={styles.financeSplitValue}>{money(received)}</Text><Text style={styles.financeSplitLabel}>recebido</Text></View><View style={styles.financeDivider}/><View><Text style={styles.financeSplitValue}>{money(pending)}</Text><Text style={styles.financeSplitLabel}>a receber</Text></View></View></Card>
    <SectionHeader eyebrow="OPERAÇÃO" title="Resumo da carteira"/><View style={styles.statsRow}><StatCard icon={UserCheck} value={String(payingClients)} label="alunos ativos"/><StatCard icon={ClipboardList} value={String(reviewSheets.length)} label={reviewSheets.length === 1 ? 'ficha a revisar' : 'fichas a revisar'} tone="dark" onPress={() => reviewSheets[0] && onClient(reviewSheets[0].client)}/></View>
    <SectionHeader eyebrow="RELATÓRIO RÁPIDO" title="Atividade dos alunos"/><Card><View style={styles.reportRow}><View><Text style={styles.reportValue}>76%</Text><Text style={styles.reportLabel}>aderência semanal</Text></View><View style={styles.miniBars}>{[42, 57, 48, 71, 63, 82].map((height, index) => <View key={index} style={[styles.miniBar, { height }, index === 5 && styles.miniBarActive]}/>)}</View></View><View style={styles.reportFoot}><Text style={styles.reportFootText}>17 alunos fizeram 3 ou mais treinos.</Text><Badge label="+12%" tone="green"/></View></Card>
    <SectionHeader eyebrow="PRIORIDADE" title="Alunos que pedem atenção" action="Ver todos"/>{clients.filter((client) => client.status !== 'Ativo').map((client) => <ClientRow key={client.id} client={client} onPress={() => onClient(client)}/>)}
  </ScrollView>;
}

export function TrainerClients({ clients, onClient, onInvite }: { clients: Client[]; onClient: (client: Client) => void; onInvite: (data: { name: string; email: string; monthlyFee: number }) => void }) {
  const [query, setQuery] = useState('');
  const [adding, setAdding] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [monthlyFee, setMonthlyFee] = useState('');
  const [inviteMessage, setInviteMessage] = useState('');
  const [inviteError, setInviteError] = useState('');
  const filtered = clients.filter((client) => client.name.toLowerCase().includes(query.toLowerCase()));
  const sendInvite = () => {
    if (!name.trim() || !email.trim()) { setInviteError('Informe o nome e o e-mail do aluno.'); return; }
    onInvite({ name: name.trim(), email: email.trim().toLowerCase(), monthlyFee: Math.max(0, Number(monthlyFee.replace(',', '.')) || 0) });
    setInviteMessage(`Convite preparado para ${email.trim().toLowerCase()}.`); setInviteError(''); setName(''); setEmail(''); setMonthlyFee(''); setAdding(false);
  };
  return <ScrollView contentContainerStyle={styles.page} keyboardShouldPersistTaps="handled"><View style={styles.exerciseTitleRow}><View><Text style={styles.pageTitle}>Alunos</Text><Text style={styles.pageDescription}>Cadastre e convide clientes para o app.</Text></View><Pressable style={styles.addExerciseButton} onPress={() => { setAdding((current) => !current); setInviteMessage(''); setInviteError(''); }}><Plus size={17} color={colors.white}/><Text style={styles.addExerciseText}>Novo</Text></Pressable></View>{adding && <Card style={styles.exerciseForm}><Text style={styles.builderTitle}>Convidar novo aluno</Text><Text style={styles.fieldLabel}>Nome completo</Text><TextInput value={name} onChangeText={setName} placeholder="Ex.: Pedro Queiroz" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>E-mail para o convite</Text><TextInput value={email} onChangeText={setEmail} autoCapitalize="none" keyboardType="email-address" placeholder="pedroqueiroz@email.com" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Mensalidade</Text><TextInput value={monthlyFee} onChangeText={setMonthlyFee} keyboardType="numeric" placeholder="Ex.: 450" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.inviteHelper}>O aluno definirá a senha pelo link do convite. Neste protótipo, o convite é apenas simulado.</Text>{inviteError ? <Text style={styles.inviteError}>{inviteError}</Text> : null}<View style={styles.editorActions}><Pressable style={[styles.outlineButton, styles.editorCancel]} onPress={() => setAdding(false)}><Text style={styles.outlineButtonText}>Cancelar</Text></Pressable><Pressable style={styles.smallPrimaryButton} onPress={sendInvite}><Text style={styles.smallPrimaryText}>Enviar convite</Text></Pressable></View></Card>}{inviteMessage ? <Text style={styles.inviteSuccess}>{inviteMessage}</Text> : null}<View style={styles.searchField}><Search size={19} color={colors.muted}/><TextInput value={query} onChangeText={setQuery} placeholder="Buscar aluno" placeholderTextColor={colors.subtle} style={styles.searchInput}/></View>{filtered.map((client) => <ClientRow key={client.id} client={client} onPress={() => onClient(client)}/>)}</ScrollView>;
}

export function TrainerExercises({ exercises, onCreate }: { exercises: Exercise[]; onCreate: (exercise: Exercise) => void }) {
  const [query, setQuery] = useState('');
  const [adding, setAdding] = useState(false);
  const [name, setName] = useState('');
  const [group, setGroup] = useState('');
  const [mediaUrl, setMediaUrl] = useState('');
  const [mediaType, setMediaType] = useState<Exercise['mediaType']>();
  const [mediaError, setMediaError] = useState('');
  const filtered = exercises.filter((exercise) => `${exercise.name} ${exercise.group}`.toLowerCase().includes(query.toLowerCase()));
  const isVideo = (exercise: Exercise) => exercise.mediaType === 'video' || Boolean(exercise.mediaUrl && /(youtube|youtu\.be|vimeo|\.mp4|\.mov)/i.test(exercise.mediaUrl));
  const pickMedia = async () => {
    const permission = await ImagePicker.requestMediaLibraryPermissionsAsync();
    if (!permission.granted) { setMediaError('Permita o acesso à galeria para selecionar uma mídia.'); return; }
    const result = await ImagePicker.launchImageLibraryAsync({ mediaTypes: ['images', 'videos'], allowsEditing: false, quality: 0.7, videoMaxDuration: 60 });
    if (result.canceled) return;
    const asset = result.assets[0];
    setMediaUrl(asset.uri); setMediaType(asset.type === 'video' ? 'video' : 'image'); setMediaError('');
  };
  const saveExercise = () => {
    if (!name.trim()) return;
    onCreate({ id: `custom-${Date.now()}`, name: name.trim(), group: group.trim() || 'Geral', mediaUrl: mediaUrl || undefined, mediaType, sets: 3, reps: '10–12', rest: '60s', previous: 0 });
    setName(''); setGroup(''); setMediaUrl(''); setMediaType(undefined); setAdding(false);
  };
  return <ScrollView contentContainerStyle={styles.page} keyboardShouldPersistTaps="handled"><View style={styles.exerciseTitleRow}><View><Text style={styles.pageTitle}>Exercícios</Text><Text style={styles.pageDescription}>Biblioteca para montar fichas.</Text></View><Pressable style={styles.addExerciseButton} onPress={() => setAdding((current) => !current)}><Plus size={17} color={colors.white}/><Text style={styles.addExerciseText}>Novo</Text></Pressable></View><View style={styles.searchField}><Search size={19} color={colors.muted}/><TextInput value={query} onChangeText={setQuery} placeholder="Buscar exercício" placeholderTextColor={colors.subtle} style={styles.searchInput}/></View>{adding && <Card style={styles.exerciseForm}><Text style={styles.builderTitle}>Cadastrar exercício</Text><Text style={styles.fieldLabel}>Nome do exercício</Text><TextInput value={name} onChangeText={setName} placeholder="Ex.: Cadeira extensora" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Grupo muscular</Text><TextInput value={group} onChangeText={setGroup} placeholder="Ex.: Quadríceps" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Mídia</Text><Pressable style={styles.galleryPicker} onPress={pickMedia}><View style={styles.galleryPickerIcon}>{mediaUrl ? (mediaType === 'video' ? <Video size={19} color={colors.primaryDark}/> : <ImageIcon size={19} color={colors.primaryDark}/>) : <ImageIcon size={19} color={colors.primaryDark}/>}</View><View style={styles.galleryPickerCopy}><Text style={styles.galleryPickerTitle}>{mediaUrl ? 'Mídia selecionada' : 'Escolher da galeria'}</Text><Text style={styles.galleryPickerDescription}>{mediaUrl ? (mediaType === 'video' ? 'Vídeo pronto para vincular' : 'Imagem pronta para vincular') : 'Foto ou vídeo do celular'}</Text></View><ChevronRight size={18} color={colors.muted}/></Pressable><Text style={[styles.mediaHelp, mediaError ? styles.mediaError : undefined]}>{mediaError || 'A mídia ficará vinculada ao exercício para uso na ficha.'}</Text><View style={styles.editorActions}><Pressable style={[styles.outlineButton, styles.editorCancel]} onPress={() => { setAdding(false); setMediaUrl(''); setMediaType(undefined); setMediaError(''); }}><Text style={styles.outlineButtonText}>Cancelar</Text></Pressable><Pressable style={styles.smallPrimaryButton} onPress={saveExercise}><Text style={styles.smallPrimaryText}>Adicionar</Text></Pressable></View></Card>}<Text style={styles.libraryCount}>{filtered.length} exercícios disponíveis</Text><View style={styles.exerciseLibrary}>{filtered.map((exercise) => <View key={exercise.id} style={styles.libraryRow}><View style={styles.libraryIcon}>{exercise.mediaUrl && !isVideo(exercise) ? <RNImage source={{ uri: exercise.mediaUrl }} style={styles.libraryMedia} /> : exercise.mediaUrl ? <Video size={18} color={colors.primary}/> : <Dumbbell size={18} color={colors.primary}/>}</View><View style={styles.clientCopy}><Text style={styles.clientName}>{exercise.name}</Text><Text style={styles.clientMeta}>Padrão: {exercise.sets} × {exercise.reps} · {exercise.rest}{exercise.mediaUrl ? ' · mídia vinculada' : ''}</Text></View><Badge label={exercise.group} tone="gray"/></View>)}</View>{!filtered.length && <Card><Text style={styles.emptyText}>Nenhum exercício encontrado.</Text></Card>}</ScrollView>;
}

export function ClientDetail({ client, plan, profile, exerciseLibrary, onBack, onSaveWeek, onCreateWorkout, onUpdateWorkout, onArchiveWorkout, onUpdateClient }: { client: Client; plan: ClientTrainingPlan; profile?: ClientProfile; exerciseLibrary: Exercise[]; onBack: () => void; onSaveWeek: (week: PlanWeek) => void; onCreateWorkout: (workout: Workout) => void; onUpdateWorkout: (workout: Workout) => void; onArchiveWorkout: (workoutId: string) => void; onUpdateClient: (client: Client, profile: ClientProfile) => void }) {
  const emptyProfile: ClientProfile = { birthDate: '', phone: '', height: '', weight: '', bodyFat: '', availability: '', note: '' };
  const [section, setSection] = useState<string>('Resumo');
  const [selectedWeekId, setSelectedWeekId] = useState(plan.weeks[0]?.id);
  const [editingWeek, setEditingWeek] = useState(false);
  const [buildingWorkout, setBuildingWorkout] = useState(false);
  const [trainingName, setTrainingName] = useState('');
  const [workoutTitle, setWorkoutTitle] = useState('');
  const [workoutFocus, setWorkoutFocus] = useState('');
  const [workoutDurationWeeks, setWorkoutDurationWeeks] = useState('');
  const [draftName, setDraftName] = useState(client.name);
  const [draftEmail, setDraftEmail] = useState(client.email);
  const [draftGoal, setDraftGoal] = useState(client.goal);
  const [draftMonthlyFee, setDraftMonthlyFee] = useState(client.monthlyFee ? String(client.monthlyFee) : '');
  const [draftProfile, setDraftProfile] = useState<ClientProfile>(profile ?? emptyProfile);
  const [registrationSaved, setRegistrationSaved] = useState(false);
  const [trainingFinished, setTrainingFinished] = useState(false);
  const [openWorkoutId, setOpenWorkoutId] = useState<string | null>(null);
  const [restoredWorkoutIds, setRestoredWorkoutIds] = useState<string[]>([]);
  const [editingWorkoutId, setEditingWorkoutId] = useState<string | null>(null);
  const selectedWeek = plan.weeks.find((week) => week.id === selectedWeekId) ?? plan.weeks[0];
  const currentWorkouts = plan.workouts.filter((workout) => workout.status !== 'archived' || restoredWorkoutIds.includes(workout.id));
  const archivedWorkouts = plan.workouts.filter((workout) => workout.status === 'archived' && !restoredWorkoutIds.includes(workout.id));
  const [selectedExerciseIds, setSelectedExerciseIds] = useState<string[]>([]);
  const saveWorkout = (exerciseConfigs: Record<string, { sets: string; reps: string; rest: string }>) => {
    const exercises = exerciseLibrary.filter((exercise) => selectedExerciseIds.includes(exercise.id)).map((exercise, index) => ({ ...exercise, id: client.id + '-workout-' + Date.now() + '-' + index, sets: Math.max(1, Number(exerciseConfigs[exercise.id]?.sets) || exercise.sets), reps: exerciseConfigs[exercise.id]?.reps.trim() || exercise.reps, rest: exerciseConfigs[exercise.id]?.rest.trim() || exercise.rest }));
    if (!exercises.length) return;
    const planDurationWeeks = Math.max(0, Number(workoutDurationWeeks) || 0);
    const expiresAt = planDurationWeeks ? new Date(Date.now() + planDurationWeeks * 7 * 86400000).toISOString() : undefined;
    onCreateWorkout({ id: client.id + '-workout-' + Date.now(), trainingName: trainingName.trim() || workoutFocus.trim(), title: workoutTitle.trim(), focus: draftGoal.trim(), duration: 0, level: 'Personalizado', status: 'current', planDurationWeeks: planDurationWeeks || undefined, expiresAt, exercises });
    setBuildingWorkout(false);
  };
  const saveRegistration = () => {
    onUpdateClient({ ...client, name: draftName.trim() || client.name, email: draftEmail.trim(), goal: draftGoal.trim(), monthlyFee: Math.max(0, Number(draftMonthlyFee.replace(',', '.')) || 0) }, draftProfile);
    setRegistrationSaved(true);
  };
  if (section === 'Plano' && trainingFinished) return <ScrollView contentContainerStyle={styles.detailPage}><Pressable style={styles.backRow} onPress={onBack}><ArrowLeft size={19} color={colors.text}/><Text style={styles.backText}>Voltar aos alunos</Text></Pressable><Text style={styles.pageTitle}>Treino concluído</Text><Text style={styles.pageDescription}>As fichas continuam disponíveis e podem ser ajustadas quando necessário.</Text><SectionHeader eyebrow="FICHAS DO TREINO" title={currentWorkouts[0]?.trainingName || 'Treino atual'}/>{currentWorkouts.map((workout) => <Card key={workout.id} style={styles.workoutRow}><View style={styles.sheetIcon}><Dumbbell size={19} color={colors.primary}/></View><View style={styles.clientCopy}><Text style={styles.clientName}>{workout.title}</Text><Text style={styles.clientMeta}>{workout.exercises.length} exercícios</Text></View><Badge label="Concluída" tone="green"/></Card>)}<Pressable style={styles.primaryButton} onPress={() => setTrainingFinished(false)}><Text style={styles.primaryButtonText}>Editar treino</Text><ChevronRight size={18} color={colors.white}/></Pressable><Text style={styles.durationHelp}>Ao editar, você poderá adicionar novas fichas sem apagar as fichas existentes.</Text></ScrollView>;
  const WorkoutCard = ({ workout, archived }: { workout: Workout; archived?: boolean }) => <Card style={styles.workoutRow}><Pressable style={styles.workoutHeader} onPress={() => setOpenWorkoutId((current) => current === workout.id ? null : workout.id)}><View style={styles.sheetIcon}><Dumbbell size={19} color={colors.primary}/></View><View style={styles.clientCopy}>{workout.trainingName ? <Text style={styles.trainingName}>{workout.trainingName}</Text> : null}<Text style={styles.clientName}>{workout.title}</Text><Text style={styles.clientMeta}>{workout.exercises.length} exercícios</Text></View><Badge label={archived ? 'Arquivada' : 'Atual'} tone={archived ? 'gray' : 'green'}/></Pressable>{openWorkoutId === workout.id && <View style={styles.workoutPreview}>{editingWorkoutId === workout.id && !archived ? <WorkoutEditor workout={workout} exerciseLibrary={exerciseLibrary} onCancel={() => setEditingWorkoutId(null)} onSave={(updated) => { onUpdateWorkout(updated); setEditingWorkoutId(null); }} /> : <><Text style={styles.previewTitle}>Exercícios da ficha</Text>{workout.exercises.map((exercise) => <Text key={exercise.id} style={styles.previewItem}>{exercise.name} · {exercise.sets} × {exercise.reps} · {exercise.rest}</Text>)}{!archived && <Pressable style={styles.archiveButton} onPress={() => setEditingWorkoutId(workout.id)}><Text style={styles.archiveButtonText}>Editar ficha</Text></Pressable>}{archived ? <Pressable style={styles.archiveButton} onPress={() => { setRestoredWorkoutIds((current) => [...current, workout.id]); setOpenWorkoutId(null); }}><Text style={styles.archiveButtonText}>Desarquivar ficha</Text></Pressable> : <Pressable style={styles.archiveButton} onPress={() => { onArchiveWorkout(workout.id); setOpenWorkoutId(null); }}><Text style={styles.archiveButtonText}>Arquivar ficha</Text></Pressable>}</>}</View>}</Card>;
  if (section === 'Plano' && !buildingWorkout) return <ScrollView contentContainerStyle={styles.detailPage} keyboardShouldPersistTaps="handled"><Pressable style={styles.backRow} onPress={() => setSection('Resumo')}><ArrowLeft size={19} color={colors.text}/><Text style={styles.backText}>Voltar para {client.name.split(' ')[0]}</Text></Pressable><Text style={styles.pageTitle}>Treino</Text><Text style={styles.pageDescription}>Um treino reúne uma ou mais fichas.</Text>{currentWorkouts.length ? <><SectionHeader eyebrow={trainingFinished ? 'TREINO CONCLUÍDO' : 'TREINO EM MONTAGEM'} title={currentWorkouts[0].trainingName || 'Treino atual'}/><Text style={styles.builderHint}>Fichas deste treino</Text>{currentWorkouts.map((workout) => <WorkoutCard key={workout.id} workout={workout}/>)}</> : <Card style={styles.emptyTraining}><Text style={styles.emptyText}>Comece criando o treino e a primeira ficha.</Text></Card>}{!trainingFinished ? <Pressable style={styles.primaryButton} onPress={() => { setWorkoutTitle(''); setWorkoutFocus(currentWorkouts[0]?.trainingName || ''); setWorkoutDurationWeeks(''); setSelectedExerciseIds([]); setBuildingWorkout(true); }}><Text style={styles.primaryButtonText}>{currentWorkouts.length ? 'Adicionar ficha ao treino' : 'Criar treino'}</Text><Plus size={18} color={colors.white}/></Pressable> : <Text style={styles.saveFeedback}>Treino concluído. As fichas continuam disponíveis para consulta.</Text>}{currentWorkouts.length && !trainingFinished ? <Pressable style={styles.outlineButton} onPress={() => setTrainingFinished(true)}><Text style={styles.outlineButtonText}>Concluir treino</Text></Pressable> : null}<SectionHeader eyebrow="HISTÓRICO" title="Fichas antigas"/>{archivedWorkouts.length ? archivedWorkouts.map((workout) => <WorkoutCard key={workout.id} workout={workout} archived/>) : <Card><Text style={styles.emptyText}>Nenhuma ficha arquivada.</Text></Card>}</ScrollView>;
  if (section === 'Plano') return <ScrollView contentContainerStyle={styles.detailPage} keyboardShouldPersistTaps="handled"><Pressable style={styles.backRow} onPress={() => setBuildingWorkout(false)}><ArrowLeft size={19} color={colors.text}/><Text style={styles.backText}>Voltar para o plano</Text></Pressable><Text style={styles.pageTitle}>Treino e fichas</Text><Text style={styles.pageDescription}>Defina o treino e monte a ficha.</Text><WorkoutBuilder client={client} exerciseLibrary={exerciseLibrary} selectedExerciseIds={selectedExerciseIds} onToggle={(exerciseId) => setSelectedExerciseIds((current) => current.includes(exerciseId) ? current.filter((id) => id !== exerciseId) : [...current, exerciseId])} workoutTitle={workoutTitle} workoutFocus={workoutFocus} workoutDurationWeeks={workoutDurationWeeks} onTitle={setWorkoutTitle} onFocus={setWorkoutFocus} onDurationWeeks={setWorkoutDurationWeeks} onSave={saveWorkout}/></ScrollView>;
  return <ScrollView contentContainerStyle={styles.detailPage} keyboardShouldPersistTaps="handled">
    <Pressable style={styles.backRow} onPress={onBack}><ArrowLeft size={19} color={colors.text}/><Text style={styles.backText}>Voltar aos alunos</Text></Pressable>
    <View style={styles.detailHeader}><Avatar initials={client.initials} size={50}/><View style={styles.detailHeaderCopy}><Text style={styles.detailName}>{client.name}</Text><Text style={styles.detailGoal}>{client.goal || 'Objetivo não informado'} · {client.lastActivity}</Text></View><Pressable onPress={() => onUpdateClient({ ...client, status: client.status === 'Inativo' ? 'Ativo' : 'Inativo' }, draftProfile)}><Badge label={client.status === 'Inativo' ? 'Reativar' : 'Inativar'} tone={client.status === 'Inativo' ? 'green' : 'red'}/></Pressable></View>
    <View style={styles.detailTabs}>{(['Resumo', 'Cadastro', 'Plano'] as const).map((item) => <Pressable key={item} onPress={() => setSection(item)} style={[styles.detailTab, section === item && styles.detailTabActive]}><Text style={[styles.detailTabText, section === item && styles.detailTabTextActive]}>{item}</Text></Pressable>)}</View>
    {section === 'Resumo' && <><SectionHeader eyebrow="TREINO" title={currentWorkouts.length ? 'Treino atual' : 'Nenhuma ficha publicada'}/>{currentWorkouts.length ? currentWorkouts.map((workout) => <WorkoutCard key={workout.id} workout={workout}/>) : <Card><Text style={styles.emptyText}>Monte a primeira ficha para este aluno.</Text></Card>}</>}
    {section === 'Cadastro' && <><SectionHeader eyebrow="DADOS DO ALUNO" title="Cadastro e avaliação"/><Card><Text style={styles.fieldLabel}>Nome completo</Text><TextInput value={draftName} onChangeText={(value) => { setDraftName(value); setRegistrationSaved(false); }} style={styles.input}/><Text style={styles.fieldLabel}>E-mail</Text><TextInput value={draftEmail} onChangeText={(value) => { setDraftEmail(value); setRegistrationSaved(false); }} autoCapitalize="none" keyboardType="email-address" style={styles.input}/><Text style={styles.fieldLabel}>Objetivo</Text><TextInput value={draftGoal} onChangeText={(value) => { setDraftGoal(value); setRegistrationSaved(false); }} placeholder="Ex.: hipertrofia" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Data de nascimento</Text><TextInput value={draftProfile.birthDate} onChangeText={(birthDate) => { setDraftProfile((current) => ({ ...current, birthDate: formatBirthDate(birthDate) })); setRegistrationSaved(false); }} placeholder="DD/MM/AAAA" placeholderTextColor={colors.subtle} keyboardType="numeric" maxLength={10} style={styles.input}/><Text style={styles.fieldLabel}>Telefone</Text><TextInput value={draftProfile.phone} onChangeText={(phone) => { setDraftProfile((current) => ({ ...current, phone })); setRegistrationSaved(false); }} keyboardType="phone-pad" style={styles.input}/><Text style={styles.fieldLabel}>Mensalidade</Text><TextInput value={draftMonthlyFee} onChangeText={(value) => { setDraftMonthlyFee(value); setRegistrationSaved(false); }} keyboardType="numeric" placeholder="Ex.: 450" placeholderTextColor={colors.subtle} style={styles.input}/></Card><SectionHeader title="Avaliação física"/><Card><Text style={styles.fieldLabel}>Altura</Text><TextInput value={draftProfile.height} onChangeText={(height) => { setDraftProfile((current) => ({ ...current, height })); setRegistrationSaved(false); }} placeholder="Ex.: 1,75 m" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Peso</Text><TextInput value={draftProfile.weight} onChangeText={(weight) => { setDraftProfile((current) => ({ ...current, weight })); setRegistrationSaved(false); }} placeholder="Ex.: 72 kg" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Percentual de gordura</Text><TextInput value={draftProfile.bodyFat} onChangeText={(bodyFat) => { setDraftProfile((current) => ({ ...current, bodyFat })); setRegistrationSaved(false); }} placeholder="Ex.: 18%" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Disponibilidade</Text><TextInput value={draftProfile.availability} onChangeText={(availability) => { setDraftProfile((current) => ({ ...current, availability })); setRegistrationSaved(false); }} placeholder="Ex.: 3x por semana" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Observações do personal</Text><TextInput value={draftProfile.note} onChangeText={(note) => { setDraftProfile((current) => ({ ...current, note })); setRegistrationSaved(false); }} multiline placeholder="Restrições, preferências e observações" placeholderTextColor={colors.subtle} style={[styles.input, styles.textArea]}/><Pressable style={[styles.primaryButton, styles.saveRegistrationButton, registrationSaved && styles.saveRegistrationButtonDone]} onPress={saveRegistration}><Text style={styles.primaryButtonText}>{registrationSaved ? 'Cadastro salvo' : 'Salvar cadastro'}</Text><Check size={18} color={colors.white}/></Pressable>{registrationSaved ? <Text style={styles.saveFeedback}>Alterações salvas no cadastro deste aluno.</Text> : null}</Card></>}
    {section === 'Plano' && <><SectionHeader eyebrow="CICLO INDIVIDUAL" title="Planejamento semanal"/>{plan.weeks.length ? <><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.weekSelector}>{plan.weeks.map((week, index) => { const active = week.id === selectedWeek?.id; return <Pressable key={week.id} onPress={() => { setSelectedWeekId(week.id); setEditingWeek(false); }} style={[styles.weekPill, active && styles.weekPillActive]}><Text style={[styles.weekNumber, active && styles.weekNumberActive]}>S{index + 1}</Text><Text style={[styles.weekPillText, active && styles.weekPillTextActive]}>{week.phase}</Text></Pressable>; })}</ScrollView>{selectedWeek && <Card style={styles.weekCard}><View style={styles.weekCardTop}><Badge label={selectedWeek.phase}/><Text style={styles.weekDate}>{selectedWeek.dateRange}</Text></View>{!editingWeek ? <><Text style={styles.weekTitle}>{selectedWeek.label}: {selectedWeek.phase}</Text><Text style={styles.cardText}>{selectedWeek.description}</Text><View style={styles.weekMetrics}><Text style={styles.weekMetric}>{selectedWeek.sessions} treinos</Text><Text style={styles.weekMetric}>{selectedWeek.intensity} intensidade</Text></View><Pressable style={styles.outlineButton} onPress={() => setEditingWeek(true)}><Text style={styles.outlineButtonText}>Editar semana</Text></Pressable></> : <WeekEditor week={selectedWeek} onCancel={() => setEditingWeek(false)} onSave={(week) => { onSaveWeek(week); setEditingWeek(false); }}/>}</Card>}</> : <Card><Text style={styles.emptyText}>Nenhuma semana cadastrada ainda.</Text></Card>}<SectionHeader eyebrow="FICHAS" title="Fichas atuais" action="Montar" onAction={() => setBuildingWorkout(!buildingWorkout)}/>{buildingWorkout && <WorkoutBuilder client={client} exerciseLibrary={exerciseLibrary} selectedExerciseIds={selectedExerciseIds} onToggle={(exerciseId) => setSelectedExerciseIds((current) => current.includes(exerciseId) ? current.filter((id) => id !== exerciseId) : [...current, exerciseId])} workoutTitle={workoutTitle} workoutFocus={workoutFocus} workoutDurationWeeks={workoutDurationWeeks} onTitle={setWorkoutTitle} onFocus={setWorkoutFocus} onDurationWeeks={setWorkoutDurationWeeks} onSave={saveWorkout}/>} {currentWorkouts.map((workout) => <WorkoutCard key={workout.id} workout={workout}/>)}<SectionHeader eyebrow="HISTÓRICO" title="Fichas antigas"/>{archivedWorkouts.length ? archivedWorkouts.map((workout) => <WorkoutCard key={workout.id} workout={workout} archived/>) : <Card><Text style={styles.emptyText}>Nenhuma ficha arquivada.</Text></Card>}</>}
  </ScrollView>;
}

function WeekEditor({ week, onCancel, onSave }: { week: PlanWeek; onCancel: () => void; onSave: (week: PlanWeek) => void }) {
  const [phase, setPhase] = useState(week.phase); const [description, setDescription] = useState(week.description); const [sessions, setSessions] = useState(String(week.sessions));
  return <><Text style={styles.fieldLabel}>Fase</Text><TextInput value={phase} onChangeText={setPhase} style={styles.input}/><Text style={styles.fieldLabel}>Orientação</Text><TextInput value={description} onChangeText={setDescription} multiline style={[styles.input, styles.textArea]}/><Text style={styles.fieldLabel}>Treinos na semana</Text><TextInput value={sessions} onChangeText={setSessions} keyboardType="numeric" style={styles.input}/><View style={styles.editorActions}><Pressable style={[styles.outlineButton, styles.editorCancel]} onPress={onCancel}><Text style={styles.outlineButtonText}>Cancelar</Text></Pressable><Pressable style={styles.smallPrimaryButton} onPress={() => onSave({ ...week, phase: phase.trim() || week.phase, description: description.trim() || week.description, sessions: Math.max(1, Number(sessions) || week.sessions) })}><Text style={styles.smallPrimaryText}>Salvar</Text></Pressable></View></>;
}

function WorkoutBuilder({ client, exerciseLibrary, selectedExerciseIds, onToggle, workoutTitle, workoutFocus, workoutDurationWeeks, onTitle, onFocus, onDurationWeeks, onSave }: { client: Client; exerciseLibrary: Workout['exercises']; selectedExerciseIds: string[]; onToggle: (id: string) => void; workoutTitle: string; workoutFocus: string; workoutDurationWeeks: string; onTitle: (value: string) => void; onFocus: (value: string) => void; onDurationWeeks: (value: string) => void; onSave: (configs: Record<string, { sets: string; reps: string; rest: string }>) => void }) {
  const [exerciseConfigs, setExerciseConfigs] = useState<Record<string, { sets: string; reps: string; rest: string }>>(() => Object.fromEntries(exerciseLibrary.map((exercise) => [exercise.id, { sets: String(exercise.sets), reps: exercise.reps, rest: exercise.rest }])));
  const [exerciseQuery, setExerciseQuery] = useState('');
  const updateConfig = (id: string, key: 'sets' | 'reps' | 'rest', value: string) => setExerciseConfigs((current) => ({ ...current, [id]: { ...(current[id] ?? { sets: '3', reps: '10–12', rest: '60 s' }), [key]: value } }));
  const filteredExercises = exerciseLibrary.filter((exercise) => exercise.name.toLocaleLowerCase('pt-BR').includes(exerciseQuery.trim().toLocaleLowerCase('pt-BR')));
  return <Card style={styles.workoutBuilder}><Text style={styles.builderTitle}>Criar treino para {client.name.split(' ')[0]}</Text><Text style={styles.builderHint}>Dê um nome ao treino e crie a primeira ficha. As próximas fichas podem usar o mesmo treino.</Text><Text style={styles.fieldLabel}>Nome do treino</Text><TextInput value={workoutFocus} onChangeText={onFocus} placeholder="Ex.: Hipertrofia - outubro" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Nome da ficha</Text><TextInput value={workoutTitle} onChangeText={onTitle} placeholder="Ex.: Ficha A - superiores" placeholderTextColor={colors.subtle} style={styles.input}/><Text style={styles.fieldLabel}>Duração da ficha <Text style={styles.optionalLabel}>(opcional)</Text></Text><View style={styles.durationField}><TextInput value={workoutDurationWeeks} onChangeText={onDurationWeeks} keyboardType="numeric" placeholder="Ex.: 4" placeholderTextColor={colors.subtle} style={styles.durationInput}/><Text style={styles.durationUnit}>semanas</Text></View><Text style={styles.durationHelp}>Preencha somente se quiser receber o aviso de revisão antes do vencimento.</Text><Text style={styles.fieldLabel}>Exercícios da ficha</Text><View style={styles.exerciseSearch}><Search size={17} color={colors.muted}/><TextInput value={exerciseQuery} onChangeText={setExerciseQuery} placeholder="Pesquisar exercício pelo nome" placeholderTextColor={colors.subtle} style={styles.exerciseSearchInput}/></View>{filteredExercises.map((exercise) => { const included = selectedExerciseIds.includes(exercise.id); const config = exerciseConfigs[exercise.id] ?? { sets: String(exercise.sets), reps: exercise.reps, rest: exercise.rest }; return <View key={exercise.id} style={[styles.exerciseRow, included && styles.exerciseRowActive]}><Pressable onPress={() => onToggle(exercise.id)} style={styles.exerciseSelector}><View style={[styles.checkBox, included && styles.checkBoxActive]}>{included && <Check size={12} color={colors.white}/>}</View><View style={styles.clientCopy}><Text style={styles.clientName}>{exercise.name}</Text><Text style={styles.clientMeta}>{exercise.group}</Text></View></Pressable>{included && <View><View style={styles.exerciseEditor}><View style={styles.compactField}><Text style={styles.compactLabel}>Séries</Text><TextInput value={config.sets} onChangeText={(value) => updateConfig(exercise.id, 'sets', value.replace(/\D/g, ''))} keyboardType="numeric" maxLength={2} style={styles.compactInput}/></View><View style={styles.compactField}><Text style={styles.compactLabel}>Repetições</Text><TextInput value={config.reps} onChangeText={(value) => updateConfig(exercise.id, 'reps', value)} placeholder="Ex.: 10–12" placeholderTextColor={colors.subtle} style={styles.compactInput}/></View></View><Text style={styles.compactLabel}>Tempo de descanso</Text><TextInput value={config.rest} onChangeText={(value) => updateConfig(exercise.id, 'rest', value)} placeholder="Ex.: 60 s" placeholderTextColor={colors.subtle} style={styles.compactInput}/></View>}</View>; })}{!filteredExercises.length ? <Text style={styles.emptyText}>Nenhum exercício encontrado.</Text> : null}<Pressable style={styles.primaryButton} onPress={() => onSave(exerciseConfigs)}><Text style={styles.primaryButtonText}>Criar ficha</Text><ChevronRight size={18} color={colors.white}/></Pressable></Card>;
}

function WorkoutEditor({ workout, exerciseLibrary, onCancel, onSave }: { workout: Workout; exerciseLibrary: Exercise[]; onCancel: () => void; onSave: (workout: Workout) => void }) {
  const [draft, setDraft] = useState<Workout>(() => ({ ...workout, exercises: workout.exercises.map((exercise) => ({ ...exercise })) }));
  const [exerciseQuery, setExerciseQuery] = useState('');
  const updateExercise = (exerciseId: string, field: keyof Exercise, value: string) => setDraft((current) => ({ ...current, exercises: current.exercises.map((exercise) => exercise.id !== exerciseId ? exercise : { ...exercise, [field]: field === 'sets' || field === 'previous' ? Math.max(0, Number(value.replace(',', '.')) || 0) : value }) }));
  const removeExercise = (exerciseId: string) => setDraft((current) => ({ ...current, exercises: current.exercises.filter((exercise) => exercise.id !== exerciseId) }));
  const addExercise = (exercise: Exercise) => setDraft((current) => current.exercises.some((item) => item.name === exercise.name) ? current : { ...current, exercises: [...current.exercises, { ...exercise, id: `${workout.id}-exercise-${Date.now()}` }] });
  const availableExercises = exerciseLibrary.filter((exercise) => !draft.exercises.some((item) => item.name === exercise.name) && exercise.name.toLocaleLowerCase('pt-BR').includes(exerciseQuery.trim().toLocaleLowerCase('pt-BR')));
  return <View><Text style={styles.previewTitle}>Editar ficha</Text><Text style={styles.fieldLabel}>Nome da ficha</Text><TextInput value={draft.title} onChangeText={(title) => setDraft((current) => ({ ...current, title }))} style={styles.input}/><Text style={styles.fieldLabel}>Exercícios desta ficha</Text>{draft.exercises.map((exercise) => <View key={exercise.id} style={styles.editExerciseCard}><View style={styles.editExerciseTop}><View style={styles.clientCopy}><Text style={styles.clientName}>{exercise.name}</Text><Text style={styles.clientMeta}>{exercise.group}</Text></View><Pressable accessibilityLabel={`Remover ${exercise.name}`} style={styles.removeExerciseButton} onPress={() => removeExercise(exercise.id)}><Trash2 size={15} color={colors.red}/></Pressable></View><View style={styles.exerciseEditor}><View style={styles.compactField}><Text style={styles.compactLabel}>Séries</Text><TextInput value={String(exercise.sets)} onChangeText={(value) => updateExercise(exercise.id, 'sets', value.replace(/\D/g, ''))} keyboardType="numeric" maxLength={2} style={styles.compactInput}/></View><View style={styles.compactField}><Text style={styles.compactLabel}>Repetições</Text><TextInput value={exercise.reps} onChangeText={(value) => updateExercise(exercise.id, 'reps', value)} style={styles.compactInput}/></View></View><View style={styles.exerciseEditor}><View style={styles.compactField}><Text style={styles.compactLabel}>Descanso</Text><TextInput value={exercise.rest} onChangeText={(value) => updateExercise(exercise.id, 'rest', value)} placeholder="Ex.: 60 s" placeholderTextColor={colors.subtle} style={styles.compactInput}/></View><View style={styles.compactField}><Text style={styles.compactLabel}>Carga sugerida</Text><TextInput value={exercise.previous ? String(exercise.previous) : ''} onChangeText={(value) => updateExercise(exercise.id, 'previous', value)} keyboardType="numeric" placeholder="kg" placeholderTextColor={colors.subtle} style={styles.compactInput}/></View></View></View>)}{!draft.exercises.length ? <Text style={styles.emptyText}>Adicione pelo menos um exercício para manter a ficha.</Text> : null}<Text style={styles.fieldLabel}>Adicionar exercício</Text><View style={styles.exerciseSearch}><Search size={17} color={colors.muted}/><TextInput value={exerciseQuery} onChangeText={setExerciseQuery} placeholder="Pesquisar exercício pelo nome" placeholderTextColor={colors.subtle} style={styles.exerciseSearchInput}/></View>{availableExercises.length ? availableExercises.map((exercise) => <Pressable key={exercise.id} style={styles.addExerciseRow} onPress={() => addExercise(exercise)}><Plus size={16} color={colors.primaryDark}/><View style={styles.clientCopy}><Text style={styles.clientName}>{exercise.name}</Text><Text style={styles.clientMeta}>{exercise.group}</Text></View><Text style={styles.addExerciseLink}>Adicionar</Text></Pressable>) : <Text style={styles.emptyText}>{exerciseQuery.trim() ? 'Nenhum exercício encontrado.' : 'Todos os exercícios da biblioteca já estão nesta ficha.'}</Text>}<View style={styles.editorActions}><Pressable style={[styles.outlineButton, styles.editorCancel]} onPress={onCancel}><Text style={styles.outlineButtonText}>Cancelar</Text></Pressable><Pressable style={styles.smallPrimaryButton} onPress={() => { if (draft.exercises.length) onSave({ ...draft, title: draft.title.trim() || workout.title }); }}><Text style={styles.smallPrimaryText}>Salvar ficha</Text></Pressable></View></View>;
}

export function TrainerPlans() {
  return <ScrollView contentContainerStyle={styles.page}><Text style={styles.pageTitle}>Relatórios</Text><Text style={styles.pageDescription}>Indicadores consolidados para acompanhar seu negócio.</Text><SectionHeader eyebrow="FINANCEIRO" title="Receita do mês"/><Card><View style={styles.reportRow}><View><Text style={styles.reportValue}>R$ 8.450</Text><Text style={styles.reportLabel}>faturamento previsto</Text></View><Badge label="+9,4%" tone="green"/></View><View style={styles.financeProgress}><View style={styles.financeProgressFill}/></View><Text style={styles.cardMeta}>85% recebido · vencimentos acompanhados</Text></Card><SectionHeader eyebrow="ALUNOS" title="Engajamento"/><Card style={styles.reportList}><ReportItem label="Treinaram esta semana" value="18 alunos" color={colors.green}/><ReportItem label="Sem treino há 7 dias" value="3 alunos" color={colors.red}/><ReportItem label="Fichas para revisar" value="5 fichas" color={colors.primary}/></Card></ScrollView>;
}

function ReportItem({ label, value, color }: { label: string; value: string; color: string }) {
  return <View style={styles.reportItem}><View style={[styles.reportBullet, { backgroundColor: color }]}/><Text style={styles.reportItemLabel}>{label}</Text><Text style={styles.reportItemValue}>{value}</Text></View>;
}

export function TrainerProfile({ onLogout }: { onLogout: () => void }) {
  return <ScrollView contentContainerStyle={styles.page}><View style={styles.profileHeader}><Avatar initials="BS" size={64}/><Text style={styles.detailName}>Bruno Silva</Text><Text style={styles.pageDescription}>Personal trainer · BS Personal</Text><Badge label="Perfil profissional"/></View><SectionHeader title="Informações profissionais"/><Card>{[['Alunos ativos', '24'], ['Especialidade', 'Hipertrofia e força'], ['CREF', '123456-G/SP']].map(([label, value], index) => <View key={label} style={[styles.infoRow, index > 0 && styles.infoBorder]}><Text style={styles.infoLabel}>{label}</Text><Text style={styles.infoValue}>{value}</Text></View>)}</Card><Pressable style={styles.logoutButton} onPress={onLogout}><Text style={styles.logoutText}>Sair da conta</Text></Pressable></ScrollView>;
}

